#### 494. 目标和
(https://leetcode.cn/problems/target-sum/)
基本回溯题:
```cpp
class Solution {
	int	 count = 0;
	void traceBack(vector<char>& signals, vector<int>& nums, int target) {
		if(signals.size() == nums.size()) {
			int sum = 0;
			for(int i = 0; i < signals.size(); i++)
				sum += (signals[i] == '+') ? nums[i] : -nums[i];
			if(sum == target)
				count++;
			return;
		}
		signals.push_back('+');
		traceBack(signals, nums, target);
		signals.pop_back();
		signals.push_back('-');
		traceBack(signals, nums, target);
		signals.pop_back();
	}

  public:
	int findTargetSumWays(vector<int>& nums, int target) {
		count = 0;
		vector<char> signals;
		traceBack(signals, nums, target);
		return count;
	}
};
```
这样做会超时，原因是每一次到叶子节点上都要计算一次表达式的值，可以将计算结果融合到遍历路径过程中
```cpp
class Solution {
	int	 count = 0;
	void traceBack(int idx, int cur_sum, vector<int>& nums, int target) {
		if(idx == nums.size()) {
			if(cur_sum == target)
				count++;
			return;
		}
		traceBack(idx + 1, cur_sum + nums[idx], nums, target);
		traceBack(idx + 1, cur_sum - nums[idx], nums, target);
	}

  public:
	int findTargetSumWays(vector<int>& nums, int target) {
		count = 0;
		traceBack(0, 0, nums, target);
		return count;
	}
};
```
- 不需要使用符号栈了，因为只有两种可能，直接将符号划归为多次 traceBack 函数调用即可
- 可以再添加一个最后一次计算时的剪枝，减少一次压栈操作，意义不大

